def solve(g, fill=4):
    from collections import Counter
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    def runs(line):
        res=[]; i=0; n=len(line)
        while i<n:
            if line[i]==bg:
                k=i
                while k<n and line[k]==bg: k+=1
                if 0<i and k<n and line[i-1]!=bg and line[k]!=bg: res.append((i,k))
                i=k
            else: i+=1
        return res
    henc=[set(range(a,b)) for i in range(h) for a,b in runs(g[i])]
    venc=[set(range(a,b)) for j in range(w) for a,b in runs([g[i][j] for i in range(h)])]
    for i in range(h):
        for j in range(w):
            if any(j in s for s in henc if True) and any(i in s for s in venc):
                # need per-row/col mapping; redo simply below
                pass
    # simpler: per-cell checks
    out=[r[:] for r in g]
    hset=[[False]*w for _ in range(h)]; vset=[[False]*w for _ in range(h)]
    for i in range(h):
        for a,b in runs(g[i]):
            for j in range(a,b): hset[i][j]=True
    for j in range(w):
        for a,b in runs([g[i][j] for i in range(h)]):
            for i in range(a,b): vset[i][j]=True
